import express from 'express';

import { query } from './db.js';
import { requireAuth, requirePermission } from './middleware/auth.js';

export const documentsRouter = express.Router();
documentsRouter.use(requireAuth);

const LOGO_DATA_URI = 'data:image/png;base64,';
const LOAN_APPLICATION_PDF_B64 = '';
const DISBURSEMENT_PDF_B64 = '';

function esc(value) {
  return String(value ?? '')
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#039;');
}

function asDate(value) {
  return value ? String(value).slice(0,10) : '';
}

function number(value) {
  const n = Number(value || 0);
  return Number.isFinite(n) ? n : 0;
}

function moneyPlain(value) {
  return new Intl.NumberFormat('en-LK', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(number(value));
}

function money(value) {
  return `Rs.${moneyPlain(value)}`;
}

function loanFrequencyWord(type) {
  const v = String(type || '').toUpperCase();
  if (v === 'DAILY') return 'Daily';
  if (v === 'MONTHLY') return 'Monthly';
  return 'Weekly';
}

async function getLoanBundle(id) {
  const result = await query(
    `
    SELECT
      vf.loan_id,
      vf.loan_code,
      vf.customer_id,
      vf.center_id,
      vf.group_id,
      vf.principal,
      vf.interest_rate,
      vf.interest_amount,
      vf.total_payable,
      vf.total_paid,
      vf.balance,
      vf.repayment_start_date,
      vf.lifecycle_status,
      vf.operational_status,
      l.loan_type,
      l.installment_count,
      l.disbursed_date,
      c.customer_code,
      c.customer_name,
      c.nic,
      c.mobile,
      c.address,
      c.default_guarantor_name,
      c.default_guarantor_nic,
      c.default_guarantor_mobile,
      ce.center_name,
      g.group_name
    FROM v_loan_financials vf
    JOIN loans l ON l.id=vf.loan_id
    JOIN customers c ON c.id=vf.customer_id
    JOIN centers ce ON ce.id=vf.center_id
    JOIN groups g ON g.id=vf.group_id
    WHERE vf.loan_id=$1
    `,
    [id]
  );

  if (result.rowCount !== 1) return null;

  const schedule = await query(
    `
    SELECT installment_no,due_date,due_amount
    FROM loan_schedule
    WHERE loan_id=$1
    ORDER BY installment_no
    `,
    [id]
  );

  return {
    loan: result.rows[0],
    schedule: schedule.rows
  };
}

function sendEmbeddedPdf(res, base64Value, filename, disposition='attachment') {
  const pdf = Buffer.from(base64Value,'base64');
  res.setHeader('Content-Type','application/pdf');
  res.setHeader(
    'Content-Disposition',
    `${disposition}; filename="${filename}"`
  );
  res.setHeader('Cache-Control','private, max-age=300');
  res.send(pdf);
}

